/* Company management and the company asset library, using the existing modal/navigation shell. */
window.createCompanyWorkspace = function(ctx){
 const {domain:c,state,task,product,products,esc,icon,btn,imageSrc,artwork,heading,render,persist,toast,openModal,closeModal,production}=ctx;
 const $=s=>document.querySelector(s),date=n=>new Date(n).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false});
 let tab='templates',editor=null,editId=null,pending=null,reference=null,assetAdvanced=false;
 let templateFilters={search:'',category:'all',media:'all',status:'all'};
 let filters={search:'',category:'all',scene:'all',media:'all',task:'all',status:'approved'};
 const option=(values,current)=>values.map(([value,label])=>`<option value="${esc(value)}" ${value===String(current)?'selected':''}>${esc(label)}</option>`).join('');
 const field=(label,id,value,type='text',extra='')=>`<label class="company-field"><span>${label}</span><input id="${id}" type="${type}" value="${esc(value)}" ${extra}></label>`;
 const select=(label,id,values,value)=>`<label class="company-field"><span>${label}</span><select id="${id}">${option(values,value)}</select></label>`;
 function page(){
  return heading('公司管理','',`<span class="company-environment">本机团队演示</span><button class="btn sm company-help-button" data-action="company-help">${icon('help')}使用说明</button>`)+`<div class="company-tabs" role="group" aria-label="公司管理分类">${[['templates','模板与标准'],['members','成员与权限'],['records','操作记录']].map(([key,name])=>`<button class="filter ${tab===key?'active':''}" data-action="company-tab" data-id="${key}" aria-pressed="${tab===key}">${name}${key==='templates'?`<span class="company-tab-count">${c.data.templates.length}</span>`:''}</button>`).join('')}</div>${tab==='templates'?templateList():tab==='members'?memberList():records()}`;
 }
 function templateList(){
  const q=templateFilters.search.trim().toLowerCase();
  const list=c.data.templates.filter(t=>{const v=c.latest(t),d=v||t.draft;return (!q||`${d.name} ${t.draft?.name||''} ${d.category}`.toLowerCase().includes(q))&&(templateFilters.category==='all'||d.category===templateFilters.category)&&(templateFilters.media==='all'||d.media===templateFilters.media)&&(templateFilters.status==='all'||templateFilters.status==='published'&&t.active&&v||templateFilters.status==='disabled'&&!t.active&&v||templateFilters.status==='draft'&&t.draft);});
  return `<div class="company-template-toolbar"><div class="search">${icon('search')}<input id="company-template-search" type="text" aria-label="搜索公司模板" placeholder="搜索模板名称" value="${esc(templateFilters.search)}"></div>${select('品类','company-template-filter-category',[['all','全部品类'],...[...new Set(c.data.templates.map(t=>(c.latest(t)||t.draft).category))].map(x=>[x,x])],templateFilters.category)}${select('媒体','company-template-filter-media',[['all','全部媒体'],['image','图片'],['video','视频']],templateFilters.media)}${select('状态','company-template-filter-status',[['all','全部状态'],['published','已发布'],['draft','草稿 / 待发布修改'],['disabled','已停用']],templateFilters.status)}<button class="btn primary" data-action="company-new-template" ${c.can('manage')?'':'disabled'}>${icon('plus')}新增模板</button></div><div class="company-template-count"><span role="status">显示 ${list.length} / ${c.data.templates.length} 个模板</span>${Object.values(templateFilters).some(x=>x&&x!=='all')?'<button class="text-button" data-action="company-clear-template-filters">清空筛选</button>':''}</div><div class="company-template-grid">${list.map(t=>{const v=c.latest(t),d=v||t.draft;return `<article class="company-template-card" data-template="${t.id}"><div class="between"><span class="tag">${esc(d.category)} · ${d.media==='video'?'视频':'图片'}</span><span class="company-template-state ${t.active?'is-published':''}">${v?(t.active?'已发布':'已停用'):'草稿'}</span></div><h3 title="${esc(d.name)}">${esc(d.name)}</h3><p class="company-template-purpose">${esc({main:'商品主图',detail:'详情素材',video:'带货视频',clip:'视频片段'}[d.purpose])}${t.draft&&v?' · 有待发布修改':''}</p><div class="company-template-spec">${esc(d.ratio)} · ${d.media==='image'?parseInt(d.quality)/1024+'K':esc(d.quality)} · ${d.count} 份${d.media==='video'?' · '+d.duration+'s':''}</div><div class="company-template-version"><span>${v?'V'+v.version+' · '+esc(v.publisher):'尚未发布'}</span><span>${v?date(v.publishedAt):''}</span></div><div class="company-card-actions"><div><button class="text-button" data-action="company-template-detail" data-id="${t.id}">查看配置</button><button class="text-button" data-action="company-template-versions" data-id="${t.id}" ${v?'':'disabled'}>版本记录</button></div><div><button class="btn sm" data-action="company-edit-template" data-id="${t.id}" ${c.can('manage')?'':'disabled'}>编辑</button>${v?`<button class="text-button" data-action="company-toggle-template" data-id="${t.id}" ${c.can('manage')?'':'disabled'}>${t.active?'停用':'启用'}</button>`:''}</div></div></article>`;}).join('')}</div>${list.length?'':'<div class="empty-state"><h3>没有符合条件的模板</h3><p>调整关键词、品类或状态后重试。</p><button class="btn sm" data-action="company-clear-template-filters">清空筛选</button></div>'}`;
 }
 function templateDetail(id){const t=c.data.templates.find(t=>t.id===id);if(!t)return;const d=c.latest(t)||t.draft;openModal('模板配置',`<p class="company-form-intro">${esc(d.name)} · ${c.latest(t)?'V'+d.version:'未发布草稿'}${t.draft&&c.latest(t)?' · 有独立草稿，编辑可查看':''}</p><dl class="detail-list"><dt>适用范围</dt><dd>${esc(d.category)} · ${d.media==='video'?'视频':'图片'} · ${esc({main:'商品主图',detail:'详情素材',video:'带货视频',clip:'视频片段'}[d.purpose])}</dd><dt>默认模型</dt><dd>${esc(d.model)}</dd><dt>画面规格</dt><dd>${esc(d.ratio)} · ${esc(d.quality)} · ${d.count} 份${d.media==='video'?' · '+d.duration+'s':''}</dd><dt>初检规则</dt><dd>商品必检 · 人物 ${d.rules.person?'启用':'关闭'} · 场景 ${d.rules.scene?'启用':'关闭'}</dd></dl><h3 class="company-config-label">默认提示词</h3><p class="company-config-prompt">${esc(d.prompt)}</p>`,btn('关闭','close-modal')+`<button class="btn primary" data-action="company-edit-template" data-id="${t.id}" ${c.can('manage')?'':'disabled'}>编辑模板</button>`);}
 function defaults(){return{name:'',category:product(task().draft.product).category,media:'image',purpose:'main',prompt:'以{{商品名称}}实拍为主体，保持{{商品事实}}，柔和光线、干净背景。',model:'公司默认模型',ratio:'1:1',quality:'2048 × 2048',count:1,duration:12,rules:{product:true,person:true,scene:true}};}
 function edit(id){c.requireRight('manage');const t=c.data.templates.find(t=>t.id===id);editId=t?.id||null;editor=c.copy(t?.draft||c.latest(t)||defaults());showEditor();}
 function capture(){if(!editor||!$('#tpl-name'))return;for(const key of ['name','category','media','purpose','prompt','model','ratio','quality','count','duration'])if($('#tpl-'+key))editor[key]=$('#tpl-'+key).value;editor.rules={product:true,person:$('#tpl-person').checked,scene:$('#tpl-scene').checked};}
 function showEditor(error=''){
  const video=editor.media==='video';openModal(editId?'编辑公司模板':'新增公司模板',`<div class="company-form"><p class="company-form-intro">保存草稿不会影响已发布版本。商品名称、SKU 与事实可使用变量，实际采用时带入。</p>${field('模板名称','tpl-name',editor.name,'text','maxlength="60" data-autofocus')}<div class="company-form-grid">${select('适用品类','tpl-category',['鞋服','美妆个护','家居日用','数码配件'].map(x=>[x,x]),editor.category)}${select('媒体','tpl-media',[['image','图片'],['video','视频']],editor.media)}${select('用途','tpl-purpose',video?[['video','带货视频'],['clip','视频片段']]:[['main','商品主图'],['detail','详情素材']],editor.purpose)}${select('模型','tpl-model',[['公司默认模型','公司默认模型'],[video?'标准视频模型 · 演示':'高保真图片模型 · 演示',video?'标准视频模型 · 演示':'高保真图片模型 · 演示']],editor.model)}</div><label class="company-field"><span>默认提示词</span><textarea id="tpl-prompt" maxlength="3000">${esc(editor.prompt)}</textarea><small>支持 {{商品名称}}、{{SKU}}、{{商品事实}}</small></label><div class="company-form-grid">${select('画面比例','tpl-ratio',['1:1','3:4','9:16','16:9'].map(x=>[x,x]),editor.ratio)}${select('清晰度','tpl-quality',(video?['1080P']:['1024 × 1024','2048 × 2048','4096 × 4096']).map(x=>[x,x]),editor.quality)}${field('默认数量','tpl-count',editor.count,'number','min="1" max="6" step="1"')}${video?select('总时长','tpl-duration',['6','12','15'].map(x=>[x,x+' 秒']),String(editor.duration)):''}</div><fieldset class="company-rule-fields"><legend>初检标准</legend><label><input type="checkbox" checked disabled>商品一致性（必检）</label><label><input id="tpl-person" type="checkbox" ${editor.rules.person?'checked':''}>人物一致性（有人物时）</label><label><input id="tpl-scene" type="checkbox" ${editor.rules.scene?'checked':''}>场景一致性</label></fieldset><div class="field-error" id="company-form-error" role="alert">${esc(error)}</div></div>`,btn('取消','close-modal')+btn('保存草稿','company-save-draft')+btn('发布版本','company-publish-preview','primary'),{wide:true});$('.overlay .modal').classList.add('company-editor');
 }
 function versions(id){const t=c.data.templates.find(t=>t.id===id);if(!t)return;openModal('模板版本记录',`<div class="company-version-list">${t.versions.slice().reverse().map(v=>`<article><div class="between"><h3>V${v.version} · ${esc(v.name)}</h3><span class="tag">${date(v.publishedAt)}</span></div><p>${esc(v.publisher)} 发布 · ${esc(v.category)} · ${esc(v.ratio)} · ${esc(v.quality)}</p><details><summary>查看当时的提示词与检查标准</summary><p class="company-history-prompt">${esc(v.prompt)}</p><p>商品一致性必检 · 人物 ${v.rules.person?'启用':'关闭'} · 场景 ${v.rules.scene?'启用':'关闭'}</p></details></article>`).join('')}</div>`,btn('关闭','close-modal'));}
 function memberList(){return `<div class="company-section-heading"><div><h2>成员与权限</h2><p>公司保留全部素材；交接只变更负责人，保留历史创建与审核身份。</p></div><button class="btn" data-action="company-identity">切换体验身份</button></div><div class="company-role-note">管理员：维护 / 创作 / 审核 / 采用 / 下载　设计师：创作 / 采用 / 下载　审核员：审核 / 下载　只读：查看。下载还受单独授权控制。</div><div class="company-member-list">${c.data.members.map(m=>`<article class="company-member-row" data-member="${m.id}"><div class="company-member-person"><span class="avatar">${esc(m.name[0])}</span><div><h3>${esc(m.name)} ${m.id===c.member().id?'<small>当前身份</small>':''}</h3><p>${c.roles[m.role]} · ${m.active?'有效':'已停用'} · ${m.download&&m.role!=='viewer'?'允许下载':'不可下载'}</p></div></div><span>${state.tasks.filter(t=>t.companyId===c.id&&t.ownerId===m.id).length} 个负责任务</span><div class="row"><button class="btn sm" data-action="company-member-edit" data-id="${m.id}" ${c.can('manage')&&m.active?'':'disabled'}>权限</button><button class="text-button" data-action="company-member-disable" data-id="${m.id}" ${c.can('manage')&&m.active&&m.id!==c.member().id?'':'disabled'}>停用并交接</button></div></article>`).join('')}</div><p class="company-footnote">身份切换用于本机体验权限差异；正式产品须由真实登录与服务端鉴权执行。</p>`;}
 function records(){return `<div class="company-record-list">${c.data.audit.map(a=>`<article><div><strong>${esc(a.action)}</strong><p>${esc(a.name)} · ${esc(a.detail||a.target)}</p></div><time>${date(a.at)}</time></article>`).join('')||'<div class="empty-state"><h3>暂无操作记录</h3><p>发布模板、引用资产与成员交接后会记录在此。</p></div>'}</div>`;}
 function identity(){openModal('切换体验身份',`<p class="company-form-intro">仅用于体验本地角色权限，当前制作和公司资产保留。</p><div class="company-identity-list">${c.data.members.filter(m=>m.active).map(m=>`<button data-action="company-switch-identity" data-id="${m.id}" class="choice-card ${m.id===c.member().id?'active':''}"><span class="avatar">${esc(m.name[0])}</span><span><strong>${esc(m.name)}</strong><small>${c.roles[m.role]}</small></span>${m.id===c.member().id?icon('check'):''}</button>`).join('')}</div>`,btn('关闭','close-modal'));}
 function chooseTemplate(target='quick'){
  const d=ctx.getDraft(target);if(!d)return;const ts=c.options(product(d.product),d.media,d.purpose);pending={taskId:task().id,target};
  openModal('选择公司模板',`<p class="company-form-intro">${esc(product(d.product).name)} · 仅显示适用品类、媒体与用途的已发布模板。</p>${ts.map(t=>{const v=c.latest(t);return `<label class="company-template-choice"><input type="radio" name="company-template-choice" value="${t.id}" ${d.templateId===t.id||ts.length===1?'checked':''}><span><strong>${esc(v.name)} <small>V${v.version}</small></strong><p>${esc(v.prompt)}</p><small>${esc(v.ratio)} · ${esc(v.quality)} · ${v.count} 份</small></span></label>`;}).join('')||'<p class="company-form-intro">暂无适用的已发布模板，请联系管理员创建或启用。</p>'}<div class="field-error" id="company-form-error" role="alert"></div>`,btn('取消','close-modal')+`<button class="btn primary" data-action="company-template-preview" ${ts.length?'':'disabled'}>核对并应用</button>`);
 }
 function library(){
  const all=c.entries(),q=filters.search.trim().toLowerCase();
  const list=all.filter(({task:t,asset:a})=>(filters.status==='all'||a.status===filters.status)&&(filters.category==='all'||product(a.product).category===filters.category)&&(filters.scene==='all'||(a.scene||'商品展示')===filters.scene)&&(filters.media==='all'||a.media===filters.media)&&(filters.task==='all'||t.id===filters.task)&&`${a.name} ${product(a.product).name} ${product(a.product).sku} ${t.name}`.toLowerCase().includes(q));
  const extraCount=['scene','task','status'].filter(k=>filters[k]!==({scene:'all',task:'all',status:'approved'}[k])).length;
  const labels={search:'搜索',category:'品类',scene:'场景',media:'媒体',task:'来源任务',status:'状态'};
  const filterText=(key,value)=>key==='task'?state.tasks.find(t=>t.id===value)?.name||value:key==='media'?(value==='image'?'图片':'视频'):key==='status'?'仅已批准':value;
  const chips=Object.entries(filters).filter(([k,v])=>k==='search'?v.trim():v!=='all').map(([k,v])=>`<button class="company-filter-chip" data-action="company-remove-filter" data-id="${k}" aria-label="移除${labels[k]}筛选：${esc(filterText(k,v))}"><span>${k==='search'?'搜索：':''}${esc(filterText(k,v))}</span>${icon('close')}</button>`).join('');
  return `<div class="company-library-filters"><div class="search">${icon('search')}<input id="company-asset-search" type="text" aria-label="搜索公司素材名称、SKU 或任务" placeholder="搜索素材、SKU 或任务" value="${esc(filters.search)}"></div>${select('品类','company-filter-category',[['all','全部品类'],...[...new Set(all.map(x=>product(x.asset.product).category))].map(x=>[x,x])],filters.category)}${select('媒体','company-filter-media',[['all','全部媒体'],['image','图片'],['video','视频']],filters.media)}<button id="company-more-filters" class="btn company-more-filters ${assetAdvanced?'active':''}" data-action="company-more-filters" aria-expanded="${assetAdvanced}" aria-controls="company-advanced-filters">${icon('filter')}更多筛选${extraCount?`<span class="company-extra-count">${extraCount}</span>`:''}${icon('down')}</button></div>${assetAdvanced?`<div id="company-advanced-filters" class="company-advanced-filters" aria-label="更多素材筛选">${select('场景','company-filter-scene',[['all','全部场景'],...[...new Set(all.map(x=>x.asset.scene||'商品展示'))].map(x=>[x,x])],filters.scene)}${select('来源任务','company-filter-task',[['all','全部任务'],...state.tasks.filter(t=>t.companyId===c.id).map(t=>[t.id,t.name])],filters.task)}${select('审核状态','company-filter-status',[['approved','已批准'],['all','全部状态']],filters.status)}</div>`:''}<div class="company-library-count"><span role="status">找到 ${list.length} 份${filters.status==='approved'?'已批准':''}素材 <span class="company-total-count">· 公司共 ${all.length} 份</span></span></div><div class="company-filter-summary ${chips?'':'is-empty'}"><div class="company-filter-chips" aria-label="已生效的筛选">${chips}</div>${chips?'<button class="text-button" data-action="company-clear-filters">重置筛选</button>':''}</div><div class="company-asset-grid">${list.map(({task:t,asset:a})=>`<article class="company-asset-card" data-company-asset="${c.referenceKey(t,a)}"><button class="asset-preview" data-action="company-asset-detail" data-id="${c.referenceKey(t,a)}" aria-label="查看${esc(a.name)}的来源与版本">${artwork(a)}${a.media==='video'?`<span class="company-media-badge">${icon('video')}${a.duration||12}s · 分镜</span>`:''}</button><div class="company-asset-info"><div class="between"><span class="tag">V${a.version} · ${a.media==='video'?'视频分镜':'图片'}</span><span class="company-asset-status">${esc({approved:'已批准',pending:'待终审',checking:'初检中',blocked:'已拦截',rejected:'已驳回',check_failed:'初检异常'}[a.status]||'未批准')}</span></div><h3 title="${esc(a.name)}">${esc(a.name)}</h3><p>${esc(product(a.product).sku)} · ${esc(a.scene||'商品展示')}</p><small title="${esc(t.name)}">来源：${esc(t.name)}</small><div class="company-card-actions"><button class="text-button" data-action="company-asset-detail" data-id="${c.referenceKey(t,a)}">来源与版本</button><button class="btn sm" data-action="company-reference" data-id="${c.referenceKey(t,a)}" ${ctx.canUse(a)&&c.can('create')?'':'disabled'}>引用至制作</button></div></div></article>`).join('')}</div>${list.length?'':'<div class="empty-state"><h3>没有符合条件的公司素材</h3><p>调整筛选，或先完成素材审核。</p><button class="btn sm" data-action="company-clear-filters">重置筛选</button></div>'}`;
 }
 function assetDetail(ref){const x=c.resolve(ref);if(!x)return;const {task:t,asset:a}=x,p=product(a.product);openModal('公司素材 · 来源与版本',`<div class="company-source-preview">${artwork(a)}</div><dl class="detail-list"><dt>素材</dt><dd>${esc(a.name)} · V${a.version}</dd><dt>来源任务</dt><dd>${esc(t.name)}</dd><dt>商品</dt><dd>${esc(p.name)} · ${esc(p.sku)}</dd><dt>创建人</dt><dd>${esc(a.creatorName||'历史成员')}</dd><dt>模板版本</dt><dd>${esc(a.snapshot?.template||p.template)}${a.snapshot?.templateVersion?' · V'+a.snapshot.templateVersion:' · 历史版本未记录'}</dd><dt>输入依据</dt><dd>${esc(a.snapshot?.factSource||p.evidence)}</dd><dt>审核状态</dt><dd>${ctx.canUse(a)?'已批准，可作为表达参考':'当前版本未获有效批准，不可引用'}</dd><dt>使用范围</dt><dd>商品成品限同 SKU 引用，新输出重新初检与人工终审。</dd></dl>`,btn('关闭','close-modal')+`<button class="btn primary" data-action="company-reference" data-id="${ref}" ${ctx.canUse(a)&&c.can('create')?'':'disabled'}>引用至制作</button>`);}
 function referenceDialog(ref){c.requireRight('create');const x=c.resolve(ref);if(!x||!ctx.canUse(x.asset))throw new Error('该来源版本已失效或未批准。');const targets=ctx.referenceTargets().filter(t=>t.draft.product===x.asset.product&&(t.draft.media==='video'||x.asset.media==='image'));reference={ref,taskId:task().id};openModal('引用到当前制作',`<p class="company-form-intro">来源：${esc(x.task.name)} · V${x.asset.version}<br>目标任务：${esc(task().name)}。仅列出同 SKU、媒体兼容且未提交的目标。</p>${targets.length?select('引用至','company-reference-target',targets.map(t=>[t.key,t.name]),targets[0].key):'<p class="company-form-intro">当前任务没有同 SKU 的兼容目标。请返回创作，明确添加商品或新建对应节点后再引用。</p>'}<p class="company-form-intro">引用保留来源和版本，不复制审核或采用状态；批量项只保留一份表达参考，应用时替换原参考。</p>`,btn('取消','close-modal')+`<button class="btn primary" data-action="company-reference-apply" ${targets.length?'':'disabled'}>确认引用</button>`);}
 function action(action,id){
  if(!action.startsWith('company-'))return false;
  try{switch(action){
   case 'company-tab':tab=['templates','members','records'].includes(id)?id:'templates';render();break;
   case 'company-help':openModal('公司管理说明','<p class="company-form-intro">已发布模板供三个制作入口明确应用。保存草稿不修改已发布标准；发布新版本不覆盖已有制作，停用后阻止新提交。成员停用时移交负责的任务与商品，保留素材、版本及审核历史。当前为本机团队演示。</p>',btn('关闭','close-modal'));break;
   case 'company-library-help':openModal('公司素材使用说明','<p class="company-form-intro">此处检索本机公司范围的全部任务素材，默认只看已批准版本。点击引用后选择目标任务内的同 SKU、媒体兼容草稿，保留来源与版本；新输出仍须独立初检和人工终审。</p>',btn('关闭','close-modal'));break;
   case 'company-template-detail':templateDetail(id);break;
   case 'company-clear-template-filters':templateFilters={search:'',category:'all',media:'all',status:'all'};render();$('#company-template-search')?.focus({preventScroll:true});break;
   case 'company-more-filters':assetAdvanced=!assetAdvanced;render();$('#company-more-filters')?.focus({preventScroll:true});break;
   case 'company-remove-filter':if(Object.hasOwn(filters,id)){filters[id]=id==='search'?'':'all';render();($('.company-filter-chip')||$('#company-asset-search'))?.focus({preventScroll:true});}break;
   case 'company-new-template':edit();break;
   case 'company-edit-template':edit(id);break;
   case 'company-template-versions':versions(id);break;
   case 'company-save-draft':capture();c.saveTemplate(editId,editor,false);persist();closeModal();render();toast('草稿已保存，已发布版本保持不变。');break;
   case 'company-publish-preview':capture();{const problem=c.validateTemplate(editor);if(problem){$('#company-form-error').textContent=problem;break;}const t=c.data.templates.find(t=>t.id===editId);openModal('确认发布模板',`<p>发布「${esc(editor.name)}」为 V${(c.latest(t)?.version||0)+1}？</p><p class="company-form-intro">新版本供后续明确应用，现有员工草稿与历史生成快照保持不变。</p>`,btn('返回编辑','company-back-editor')+btn('确认发布','company-confirm-publish','primary'));}break;
   case 'company-back-editor':showEditor();break;
   case 'company-confirm-publish':c.saveTemplate(editId,editor,true);persist();closeModal();render();toast('新版本已发布，可在三个制作入口选择应用。');break;
   case 'company-toggle-template':{c.requireRight('manage');const t=c.data.templates.find(t=>t.id===id);openModal(t.active?'停用模板？':'启用模板？',`<p>${t.active?'停用后阻止新的生成提交，已提交执行和历史素材保留。':'启用后可供员工选择最新已发布版本。'}</p>`,btn('取消','close-modal')+`<button class="btn primary" data-action="company-confirm-toggle" data-id="${id}">确认${t.active?'停用':'启用'}</button>`);break;}
   case 'company-confirm-toggle':c.toggleTemplate(id);persist();closeModal();render();break;
   case 'company-identity':identity();break;
   case 'company-switch-identity':ctx.syncDraft();c.switchMember(id);closeModal();persist();render();toast('已切换为'+c.member().name+' · '+c.roles[c.member().role]);break;
   case 'company-member-edit':{c.requireRight('manage');const m=c.data.members.find(m=>m.id===id);openModal('成员权限',select('角色','company-member-role',Object.entries(c.roles),m.role)+`<label class="checkbox-label"><input id="company-member-download" type="checkbox" ${m.download?'checked':''}>允许下载（仍受角色限制）</label><div class="field-error" id="company-form-error" role="alert"></div>`,btn('取消','close-modal')+`<button class="btn primary" data-action="company-member-save" data-id="${id}">保存权限</button>`);break;}
   case 'company-member-save':c.updateMember(id,$('#company-member-role').value,$('#company-member-download').checked);persist();closeModal();render();break;
   case 'company-member-disable':{c.requireRight('manage');const m=c.data.members.find(m=>m.id===id),next=c.data.members.filter(m=>m.active&&m.id!==id&&['admin','designer'].includes(m.role));openModal('停用成员并交接',`<p>停用 ${esc(m.name)}，并移交其负责的任务和商品。</p>${select('接手人','company-member-successor',next.map(m=>[m.id,m.name+' · '+c.roles[m.role]]),next[0]?.id)}<p class="company-form-intro">原素材、创建人、版本和审核决定全部保留；停用后该身份不能进入。</p><div class="field-error" id="company-form-error" role="alert"></div>`,btn('取消','close-modal')+`<button class="btn danger" data-action="company-member-confirm-disable" data-id="${id}">确认停用并交接</button>`);break;}
   case 'company-member-confirm-disable':c.disableMember(id,$('#company-member-successor').value);persist();closeModal();render();toast('成员已停用，任务和商品已交接，历史素材保留。');break;
   case 'company-choose-template':chooseTemplate(id);break;
   case 'company-template-preview':{const selected=$('[name="company-template-choice"]:checked');if(!selected){$('#company-form-error').textContent='请选择一份模板。';break;}const t=c.data.templates.find(t=>t.id===selected.value);pending={...pending,templateId:t.id,version:c.latest(t).version};openModal('应用模板配置？',`<p>应用「${esc(c.latest(t).name)}」V${pending.version}，将替换当前提示词和默认参数。</p><p class="company-form-intro">商品事实与独立引用保留；不会自动生成，其他项及已提交记录不变。</p>`,btn('取消','close-modal')+btn('确认应用','company-template-apply','primary'));break;}
   case 'company-template-apply':c.requireRight('create');if(pending.taskId!==task().id)throw new Error('任务已变化，请重新选择。');ctx.applyTemplate(pending);persist();closeModal();render();toast('模板已应用，可继续编辑，尚未启动生成。');break;
   case 'company-clear-filters':filters={search:'',category:'all',scene:'all',media:'all',task:'all',status:'approved'};render();$('#company-asset-search')?.focus({preventScroll:true});break;
   case 'company-asset-detail':assetDetail(id);break;
   case 'company-reference':referenceDialog(id);break;
   case 'company-reference-apply':c.requireRight('create');if(reference.taskId!==task().id)throw new Error('任务已变化，请重新引用。');ctx.applyReference($('#company-reference-target').value,reference.ref);c.audit('引用公司素材',reference.ref,task().name);persist();closeModal();render();toast('已引用批准版本，保留来源；新输出仍需初检与终审。');break;
  }}catch(e){const field=$('#company-form-error');if(field)field.textContent=e.message;else toast(e.message);}return true;
 }
 function input(el){if(el.id==='company-template-search'){templateFilters.search=el.value;render();return true;}if(el.id==='company-asset-search'){filters.search=el.value;render();return true;}return el.id?.startsWith('tpl-')||false;}
 function change(el){if(el.id?.startsWith('company-template-filter-')){templateFilters[el.id.slice(24)]=el.value;render();return true;}if(el.id?.startsWith('company-filter-')){filters[el.id.slice(15)]=el.value;render();return true;}if(el.id==='tpl-media'){capture();const video=editor.media==='video';editor.purpose=video?'video':'main';editor.quality=video?'1080P':'2048 × 2048';editor.model='公司默认模型';showEditor();return true;}return false;}
 return{page,library,action,input,change,identity};
};
